document.addEventListener('DOMContentLoaded', async function () {
        // Get URL parameters to populate form fields
        const urlParams = new URLSearchParams(window.location.search);

        const areaIdParam = urlParams.get('commonFilter.AreaId');
        // Fetch location dropdown areas
        const select = document.getElementById("location");

        try {
            const response = await fetch("/api/areas");
            if (!response.ok) throw new Error("Failed to fetch areas");

            const areas = await response.json();
            areas.forEach(area => {
                const option = document.createElement("option");
                option.value = area.id;
                option.textContent = area.name;
                if (areaIdParam && area.id.toString() === areaIdParam) {
                    option.selected = true;
                }
                select.appendChild(option);
            });
            // Initialize Choices.js after options are populated
            if (window.locationChoices) {
                window.locationChoices.destroy();
            }
            window.locationChoices = new Choices(select, {
                searchEnabled: false,
                itemSelectText: '',
                shouldSort: false,
                placeholder: true,
                placeholderValue: 'select-location',
                classNames: {
                    containerOuter: 'choices-custom-location'
                }
            });

            if (areaIdParam) {
                window.locationChoices.setChoiceByValue(areaIdParam);
            } 
        } catch (error) {
            console.error("Error loading areas:", error);
        }

        function updateHiddenFields() {
            // Set values to empty string when value is null (dash state), otherwise set the actual value
            document.getElementById('hiddenAdults').value = counters.adults.value !== null ? counters.adults.value : '';
            document.getElementById('hiddenChildren').value = counters.children.value !== null ? counters.children.value : '';
            document.getElementById('hiddenRooms').value = counters.rooms.value !== null ? counters.rooms.value : '';
        }

        const petsToggle = document.getElementById('petsToggle');
        const hiddenPets = document.getElementById('hiddenPetsAllowed');

        // Populate pets toggle from URL
        const petsParam = urlParams.get('commonFilter.PetsAllowed');
        if (petsParam === 'true') {
            petsToggle.checked = true;
            hiddenPets.value = 'true';
        }

        petsToggle.addEventListener('change', function () {
            hiddenPets.value = petsToggle.checked ? 'true' : 'false';
        });

        // Custom dropdown with counters
        const dropdown = document.getElementById('guestDropdown');
        const optionsDisplay = document.getElementById('optionsDisplay');

        const counters = {
            adults: {
                elem: document.getElementById('adultsCount'),
                value: null,
                min: null,
                max: null,
                hasInteracted: false
            },
            children: {
                elem: document.getElementById('childrenCount'),
                value: null,
                min: null,
                max: null,
                hasInteracted: false
            },
            rooms: {
                elem: document.getElementById('roomsCount'),
                value: null,
                min: null,
                max: null,
                hasInteracted: false
            }
        };

        // Populate counters from URL parameters
        const adultsParam = urlParams.get('commonFilter.Adults');
        const childrenParam = urlParams.get('commonFilter.Children');
        const roomsParam = urlParams.get('commonFilter.Rooms');

        if (adultsParam && adultsParam !== '') {
            const adultsValue = parseInt(adultsParam);
            if (!isNaN(adultsValue) && adultsValue > 0) {
                counters.adults.value = adultsValue;
                counters.adults.hasInteracted = true;
            }
        }

        if (childrenParam && childrenParam !== '') {
            const childrenValue = parseInt(childrenParam);
            if (!isNaN(childrenValue) && childrenValue > 0) {
                counters.children.value = childrenValue;
                counters.children.hasInteracted = true;
            }
        }

        if (roomsParam && roomsParam !== '') {
            const roomsValue = parseInt(roomsParam);
            if (!isNaN(roomsValue) && roomsValue > 0) {
                counters.rooms.value = roomsValue;
                counters.rooms.hasInteracted = true;
            }
        }

        Object.keys(counters).forEach(key => {
            const counter = counters[key];
            counter.elem.textContent = counter.value !== null ? counter.value : '—';
        });

        function updateSelectText() {
            const {adults, children, rooms} = counters;
            const adultsText = adults.value !== null ? adults.value : '—';
            const childrenText = children.value !== null ? children.value : '—';
            const roomsText = rooms.value !== null ? rooms.value : '—';
            const htmlLang = document.documentElement.lang.toLowerCase();
            const isArabic = htmlLang.split("-")[0] === 'ar';
            var text = `${adultsText} Adults, ${childrenText} Children, ${roomsText} Bedroom${rooms.value !== 1 ? 's' : ''}`;
            if (isArabic) {
                text = `${adultsText} بالغون, ${childrenText} اطفال, ${roomsText} غرف نوم${rooms.value !== 1 ? '' : 'ة'}`;
            }

            optionsDisplay.textContent = text;
        }

        updateSelectText();
        updateHiddenFields();

        optionsDisplay.addEventListener('click', function (e) {
            e.preventDefault();
            e.stopPropagation();
            dropdown.classList.toggle('dropdown-open');
        });

        document.addEventListener('click', function (e) {
            if (!dropdown.contains(e.target)) {
                dropdown.classList.remove('dropdown-open');
            }
        });

        // Counter logic
        document.querySelectorAll('.counter-btn').forEach(btn => {
            btn.addEventListener('click', function () {
                const row = this.closest('.option-row');
                const optionNameElement = row.querySelector('.option-name');
                const counterType = optionNameElement.getAttribute('data-counter');
                const isPlus = this.classList.contains('plus');

                if (counterType && counters[counterType]) {
                    const counter = counters[counterType];

                    if (isPlus) {
                        // First interaction: set to 1, then increment normally
                        if (counter.value === null) {
                            counter.value = 1;
                            counter.hasInteracted = true;
                        } else {
                            counter.value++;
                        }
                    } else {
                        // Minus button
                        if (counter.value === null) {
                            // Do nothing if it's null and user presses minus
                            return;
                        }
                        if (counter.value > 1) {
                            counter.value--;
                        } else if (counter.value === 1) {
                            // If it reaches 1 and user presses minus, go back to null (dash)
                            counter.value = null;
                            counter.hasInteracted = false;
                        }
                    }

                    // Update display
                    counter.elem.textContent = counter.value !== null ? counter.value : '—';
                    updateSelectText();
                    updateHiddenFields();
                }
            });
        });

    window.calendar = new CustomCalendar();
    window.calendar.init();
    const checkInParam = urlParams.get('checkInStr');
    const checkOutParam = urlParams.get('checkOutStr');
    const flexibilityParam = urlParams.get('commonFilter.FlexibilityInDays') || '0';

    if (checkInParam && checkOutParam) {
        window.calendar.setDates(checkInParam, checkOutParam, parseInt(flexibilityParam));
    }
        // Open calendar when date inputs are clicked
    document.querySelectorAll('.date-group').forEach(group => {
        group.addEventListener('click', function () {
            window.calendar.open();
        });
    });
    });
