    .choices-custom-location .choices__placeholder,
    .choices-custom-location .choices__item--selectable.is-selected {
        color: #333333 !important; /* Gray color for selected item and placeholder */
        background: transparent !important; /* Transparent background */
    }

        .choices-custom-location .choices__item--selectable {
            text-align: justify;
            color: #000 !important;
            font-weight: normal !important;
        }
    /* Style for the dropdown list */
    .choices-custom-location .choices__list--dropdown,
    .choices-custom-location .choices__list[aria-expanded] {
        border-radius: 24px; /* Rounded corners */
        background-color: #f8f5ef; /* Light beige background */
