        min-width: 260px; /* Minimum width for dropdown */
        box-shadow: 0 6px 24px rgba(0, 0, 0, 0.08); /* Subtle shadow */
        padding: 8px 0; /* Padding for dropdown */
        z-index: 1000; /* Ensure dropdown appears above other elements */
    }

    /* Style for selectable items in the dropdown */
    .choices-custom-location .choices__item--selectable {
        padding: 1px 4px; /* Reduce padding */
        line-height: 1; /* Adjust line height */
        font-size: 13px; /* Font size for items */
