        font-weight: bold; /* Bold text */
        background: transparent; /* Transparent background */
        transition: background 0.2s, color 0.2s; /* Smooth transition for hover effects */
    }

    /* Hover and highlight styles for selectable items */
    .choices-custom-location .choices__item--selectable.is-highlighted,
    .choices-custom-location .choices__item--selectable:hover {
        background-color: #e9e1d3; /* Light beige background on hover */
        color: #000; /* Black text color */
    }

    /* Reset styles for the closed select dropdown */
    .choices-custom-location .choices__inner {
        background: transparent !important; /* Transparent background */
        border: none !important; /* Remove border */
        border-radius: 0 !important; /* Remove border radius */
