    /* Toggle Switch */
    .toggle-switch {
        position: relative;
        display: inline-block;
        width: 48px;
        height: 24px;
        flex-shrink: 0;
        margin-left: auto;
    }

    html[dir="rtl"] .toggle-switch {
        margin-left: 0;
        margin-right: auto;
    }

    .toggle-switch input {
        opacity: 0;
        width: 0;
        height: 0;
    }

    .toggle-slider {
        position: absolute;
        cursor: pointer;
        top: 0;
        left: 0;
        right: 0;
        bottom: 0;
        background-color: #ccc;
        transition: .4s;
        border-radius: 24px;
    }

    .toggle-slider:before {
        position: absolute;
        content: "";
        height: 20px;
        width: 20px;
        left: 2px;
        bottom: 2px;
        background-color: white;
        transition: .4s;
        border-radius: 50%;
    }

    html[dir="rtl"] .toggle-slider:before {
        left: auto;
        right: 2px;
    }

    input:checked + .toggle-slider {
        background-color: #207d9c;
    }

    input:checked + .toggle-slider:before {
        transform: translateX(24px);
    }

    html[dir="rtl"] input:checked + .toggle-slider:before {
        transform: translateX(-24px);
    }

