    // Reviews functionality
    let allReviews = [];
    let currentPage = 0;
    let totalPages = 0;
    let reviewsPerPage;

    const reviewsContainer = document.getElementById('reviewsContainer');
    const prevBtn = document.getElementById('prev-review');
    const nextBtn = document.getElementById('next-review');

    function getReviewsPerPage() {
        return window.innerWidth < 768 ? 1 : (window.innerWidth < 992 ? 2 : 3);
    }

        async function fetchReviews() {
        try {
            const res = await fetch("/api/reviews");
            const data = await res.json();

            if (!Array.isArray(data) || data.length === 0 || data.length ===1 || data.length ===2 ) {
                throw new Error("Empty or invalid data");
            }

            allReviews = data;
        } catch (err) {
            console.warn("Using reviews due to error:", err.message);

            allReviews = [
                {
                    name: "Sarah M.",
                    text: "Absolutely stunning property and the check-in process was so smooth. Highly recommended!",
                    rating: 5,
                    time: "2 days ago"
                },
                {
                    name: "Ahmed T.",
                    text: "The place was clean, well-equipped, and just steps from the beach. Loved it!",
                    rating: 4.5,
                    time: "1 week ago"
                },
                {
                    name: "Noura K.",
                    text: "Great experience overall, especially the hospitality and fast support team response.",
                    rating: 4.8,
                    time: "3 days ago"
                }
            ];
        }

        updateReviewsPerPage();
        renderReviews();
    }


    function updateReviewsPerPage() {
        reviewsPerPage = getReviewsPerPage();
        totalPages = Math.ceil(allReviews.length / reviewsPerPage);
    }

    function createReviewCard(review) {
        return `
            <div class="col-12 col-md-6 col-lg-4">
                <div class="custom-review-card p-4 h-100 shadow-sm">                    <div class="d-flex align-items-center mb-2">
                        <div class="p-2 me-2">
                            <img src="/Images/Icons/Avatars.svg" alt="User avatar" />
                        </div>
                        <h6 class="mb-0 fw-semibold" style="color:#007D9C;">${review.name}</h6>
                    </div>
                    <p class="small mt-2 mb-3">${review.text}</p>
                    <div class="d-flex justify-content-between align-items-center">
                        <div><i class="fa fa-star text-warning"></i> ${review.rating}</div>
                        <small style="color:#007D9C;">${review.time}</small>
                    </div>
                </div>
            </div>
        `;
    }

    function renderReviews() {
        reviewsContainer.innerHTML = '';
        const startIndex = currentPage * reviewsPerPage;
        const endIndex = Math.min(startIndex + reviewsPerPage, allReviews.length);
        const currentReviews = allReviews.slice(startIndex, endIndex);

        let reviewsHTML = '';
        currentReviews.forEach(review => {
            reviewsHTML += createReviewCard(review);
        });

        reviewsContainer.innerHTML = reviewsHTML;
        updateNavigationState();
    }

    function updateNavigationState() {
        const navigationElement = document.querySelector('.reviews-navigation');
        navigationElement.style.display = allReviews.length > reviewsPerPage ? 'flex' : 'none';

        prevBtn.disabled = currentPage === 0;
        nextBtn.disabled = currentPage >= totalPages - 1;
    }

    prevBtn.addEventListener('click', function() {
        if (currentPage > 0) {
            currentPage--;
            renderReviews();
        }
    });

    nextBtn.addEventListener('click', function() {
        if (currentPage < totalPages - 1) {
            currentPage++;
            renderReviews();
        }
    });

    window.addEventListener('resize', function() {
        const newReviewsPerPage = getReviewsPerPage();
        if (newReviewsPerPage !== reviewsPerPage) {
            const firstVisibleIndex = currentPage * reviewsPerPage;
            updateReviewsPerPage();
            currentPage = Math.floor(firstVisibleIndex / reviewsPerPage);
            renderReviews();
        }
    });
        const layer1Wrapper = document.querySelector('.layer1-wrapper');
        const popularListingsTitle = document.getElementById('popularListingsTitle');

    function updateLayer1Position() {
        if (!layer1Wrapper || !popularListingsSection || !popularListingsTitle) return;

        const titleRect = popularListingsTitle.getBoundingClientRect();
        const sectionRect = popularListingsSection.getBoundingClientRect();

        const titleTop = titleRect.top + window.scrollY;
        const sectionBottom = sectionRect.bottom + window.scrollY;
        const height = Math.max(0, sectionBottom - titleTop);

        layer1Wrapper.style.top = titleTop + 'px';
        layer1Wrapper.style.height = height + 'px';
    }

    function ensureSectionBelowHero() {
        if (!backgroundMain || !popularListingsSection) return;
        popularListingsSection.style.marginTop = '';
        const bgBottom = backgroundMain.getBoundingClientRect().bottom + window.scrollY;
        const sectionTop = popularListingsSection.getBoundingClientRect().top + window.scrollY;
        const overlap = bgBottom - sectionTop;
        const spacing = 0;
        if (overlap > 0) {
            popularListingsSection.style.marginTop = (overlap + spacing) + 'px';
        }
        updateLayer1Position();
    }

    ensureSectionBelowHero();
    window.addEventListener('resize', ensureSectionBelowHero);
    window.addEventListener('scroll', updateLayer1Position);
    window.addEventListener('load', ensureSectionBelowHero);

    fetchReviews();

        //FAQ
         const accordion = document.getElementById("faqAccordion");

    try {
        const response = await fetch("/api/faqs");
        const faqs = await response.json();

        accordion.innerHTML = ""; // Clear existing content

        faqs.forEach((faq, index) => {
            const id = `faq${index + 1}`;
            const item = `
                <div class="accordion-item border mb-2">
                    <h2 class="accordion-header">
                        <button class="accordion-button custom-faq-button collapsed" type="button"
                                data-bs-toggle="collapse" data-bs-target="#${id}">
                            <span class="faq-icon">+</span>
                            <span class="faq-text" style= "font-weight:550;">  ${faq.question}</span>
                        </button>
                    </h2>
                    <div id="${id}" class="accordion-collapse collapse" data-bs-parent="#faqAccordion">
                        <div class="accordion-body small">
                            ${faq.answer}
                        </div>
                    </div>
                </div>
            `;
            accordion.insertAdjacentHTML("beforeend", item);
        });

        // Add collapse toggle behavior
        const accordionItems = document.querySelectorAll(".accordion-item");
        accordionItems.forEach(item => {
            const button = item.querySelector(".accordion-button");
            const icon = button.querySelector(".faq-icon");
            const collapseId = button.getAttribute("data-bs-target");
            const collapseEl = document.querySelector(collapseId);

            collapseEl.addEventListener("show.bs.collapse", () => {
                icon.textContent = "–";
                item.classList.add("show-bg");
            });

            collapseEl.addEventListener("hide.bs.collapse", () => {
                icon.textContent = "+";
                item.classList.remove("show-bg");
            });
        });

    } catch (error) {
        console.error("Failed to load FAQs:", error);
        accordion.innerHTML = `<p class="text-danger">Failed to load FAQs.</p>`;
    }
